    def _verify_post_remove_state(self) -> dict[str, Any]:
        baseline = self.pre_remove_baseline
        if not isinstance(baseline, dict):
            raise Deny("remove_baseline_missing")
        index = self._case_index()
        before = baseline["index"]
        if (
            index.get("v") != before.get("v")
            or index.get("case_id") != before.get("case_id")
            or index.get("next_seq") != before.get("next_seq")
            or len(index["materials"]) != len(before["materials"])
        ):
            raise Deny("remove_index_envelope")
        after_by_id = {
            item.get("material_id"): item
            for item in index["materials"]
            if isinstance(item, dict)
        }
        before_by_id = {
            item.get("material_id"): item
            for item in before["materials"]
            if isinstance(item, dict)
        }
        if set(after_by_id) != set(before_by_id) or len(after_by_id) != 3:
            raise Deny("remove_index_ids")
        target = after_by_id.get(TARGET_MATERIAL_ID)
        before_target = before_by_id.get(TARGET_MATERIAL_ID)
        if not isinstance(target, dict) or not isinstance(before_target, dict):
            raise Deny("remove_target_missing")
        immutable_target = (
            "material_id",
            "name",
            "type",
            "rel_path",
            "size",
            "mtime",
            "sha256",
            "unit",
            "unit_count",
            "is_ocr",
            "text_path",
            "origin",
        )
        if (
            any(target.get(key) != before_target.get(key) for key in immutable_target)
            or target.get("status") != "removed"
            or target.get("pages_need_ocr") != []
            or target.get("pages_mixed") != []
            or target.get("error") is not None
            or not isinstance(target.get("updated_at"), str)
        ):
            raise Deny("remove_target_tombstone")
        remaining_ids = set(after_by_id) - {TARGET_MATERIAL_ID}
        if remaining_ids != set(baseline["remaining_index"]) or any(
            after_by_id[mid] != baseline["remaining_index"][mid]
            for mid in remaining_ids
        ):
            raise Deny("remove_remaining_index_identity")
        target_copy = pathlib.Path(baseline["target_copy"]["path"])
        target_text = pathlib.Path(baseline["target_text"]["path"])
        if os.path.lexists(target_copy) or os.path.lexists(target_text):
            raise Deny("remove_target_copy_or_text_present")
        remaining_texts = {
            mid: self._material_text_identity(after_by_id[mid])
            for mid in remaining_ids
        }
        if remaining_texts != baseline["remaining_texts"]:
            raise Deny("remove_remaining_text_identity")
        if self._external_input_identity() != self.external_before:
            raise Deny("external_input_changed_by_remove")
        self._verify_after_remove_without_material()
        return {
            "target_material_id": TARGET_MATERIAL_ID,
            "target_status": target["status"],
            "target_sha256": target["sha256"],
            "target_case_copy_present": False,
            "target_text_present": False,
            "remaining_ids": sorted(remaining_ids),
            "remaining_index_unchanged": True,
            "remaining_texts_unchanged": True,
            "index_bytes_after": _file_identity(
                self.case / "工作区" / "材料" / "index.json"
