            return self._deny("TASK_BEGIN_REPLAY_QUERY")
        if not self._exact_keys(data, {"session_id", "cwd", "request_id"}):
            return self._deny("TASK_BEGIN_REPLAY_BODY")
        if (
            data["session_id"] != self.SESSION_ID
            or data["cwd"] != str(self.case)
            or data["request_id"] != self.request_id
        ):
            return self._deny("TASK_BEGIN_REPLAY_IDENTITY")
        with self.lock:
            if (
                self.phase != "await_begin_replay"
                or self.inflight is not None
                or self.replay_begin_attempts != 0
