    def _complete_begin_replay(self, status: int | None, response: Any) -> None:
        if status != 200 or response != self.TASK_NOT_FOUND_FAILURE:
            raise Deny("TASK_BEGIN_REPLAY_EXPECTED_NATIVE_DENIAL_MISSING")
        if (
            self.task_before_repeat is None
            or self._task_file_identity(self.task_id) != self.task_before_repeat
